import { useState } from 'react';

interface CounterProps {
  initial?: number;
}

export default function Counter({ initial = 0 }: CounterProps) {
  const [count, setCount] = useState(initial);

  return (
    <div className="flex flex-col items-center gap-4 p-6 rounded-xl bg-[#11111b] border border-[#1e1e2e]">
      <h2 className="text-lg font-bold">Counter: {count}</h2>
      <div className="flex gap-2">
        <button onClick={() => setCount(c => c - 1)} className="px-4 py-2 rounded-lg bg-[#1e1e2e] hover:bg-[#2a2a3e]">-1</button>
        <button onClick={() => setCount(0)} className="px-4 py-2 rounded-lg bg-[#1e1e2e] hover:bg-[#2a2a3e]">Reset</button>
        <button onClick={() => setCount(c => c + 1)} className="px-4 py-2 rounded-lg bg-violet-600 hover:bg-violet-700">+1</button>
      </div>
      <p className="text-xs text-slate-500">Template AI Provider OS - React</p>
    </div>
  );
}
